import{z as s,x as l,o as t,c as d,q as A,j as B,D as E,d as n,s as i,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"竞价阶段的微观结构","description":"","frontmatter":{"title":"竞价阶段的微观结构","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/obd-auction-microstructure.md","filePath":"quant/obd-auction-microstructure.md","lastUpdated":1791413859000}'),u={name:"quant/obd-auction-microstructure.md"};function p(h,a,c,m,D,f){const r=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=A('<h1 id="竞价阶段的微观结构" tabindex="-1">竞价阶段的微观结构 <a class="header-anchor" href="#竞价阶段的微观结构" aria-label="Permalink to &quot;竞价阶段的微观结构&quot;">​</a></h1><div class="epigraph"><p>竞价把一段时间的信息积累压缩成一次定价：没有时间优先，供需曲线一次相交——用连续市场的直觉读它，条条错位。</p><footer>—— 据 Harris, Trading and Exchanges, 2003；Budish, Cramton and Shim, Quarterly Journal of Economics, 2015 整理</footer></div><p><a href="/quant/obd-intraday-seasonality">上一课</a>把形状整体搬家登记成制度事件，清单里拍卖规则修改排在最前；日内两端的峰也由竞价造成。本课写这个机制：主干已有 <a href="/quant/opening-closing-call">开盘与收盘集合竞价</a>、<a href="/quant/continuous-vs-auction">连续与竞价的取舍</a>与<a href="/quant/closing-auction-design">收盘竞价的设计</a>；本课深钻竞价内部——指示价与失衡怎么演化、清算价怎么形成、订单怎么博弈，以及把竞价错当连续会错在哪。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>竞价是单一价格的批量清算：订单在窗口内积累成供需曲线，一次相交出清，没有时间优先。连续段的统计直觉在这里整体失效：竞价 print 是清算价不是边际成交，开盘跳空不是第一笔市价冲击，点差在竞价里没有通常含义。把竞价数据混进连续段的冲击估计、点差统计与毒性度量，第一、二、四课的产出逐项被污染。缺口是给竞价建立自己的口径。</p><p><span class="marginnote">术语翻译：集合竞价就是「先攒单、后一次性成交」——窗口内大家只下单不撮合，时间一到把所有买卖单各排成一条供需曲线，取能让成交量最大的那个价格，所有人按同一价成交。</span></p><h3 id="指示价与失衡的演化" tabindex="-1">指示价与失衡的演化 <a class="header-anchor" href="#指示价与失衡的演化" aria-label="Permalink to &quot;指示价与失衡的演化&quot;">​</a></h3><p>竞价窗口内可观测的是指示价与指示失衡：每笔新订单进入，理论出清价与未配对方向随之更新。这条更新路径是竞价的「动力学」：信息随订单积累逐步揭示，而非瞬间揭晓。指示失衡是公开的方向信号——自我实现（吸引同向单）又自我限制（吸引反向单），两力的对比决定价格发现效率。指示值的公布时点是信息集跳变：公布前后的提交博弈结构不同。</p><p><span class="marginnote">收盘竞价的成交占比在指数再平衡与衍生品到期日成倍抬升——正是上一课的「形状搬家日」。当普通日平均，收盘峰被系统性高估，且永远查不出原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建模分三块。清算规则：出清价取成交量最大化价格，同量时的次优价格规则决定边界订单的归宿——规则细节改变行为，跨市场比较先对规则。提交博弈：指示价透明时，早挂暴露意图、晚挂承担不成交风险，尾盘偷袭与反偷袭集中于窗口末端；收盘占比大的市场，指数与被动资金把执行压进竞价，套利者围绕公布的失衡下注。数据口径：竞价订单流单独建事件字典，速率与连续段分开估——第一课按会话分段在这里走到底。批量清算还有一层制度含义：频繁批量拍卖用时间离散化取消竞速，<a href="/quant/frequent-batch-auction">Budish, Cramton and Shim</a> 的论点——本课把它当作机制光谱的一端。</p>',11)),(t(),B(o,null,{default:E(()=>[i(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%E8%AE%A2%E5%8D%95%E8%BF%9B%E5%85%A5%22%5D%20--%3E%20IND%5B%22%E6%8C%87%E7%A4%BA%E4%BB%B7%E4%B8%8E%E5%A4%B1%E8%A1%A1%E6%9B%B4%E6%96%B0%22%5D%0A%20%20IND%20--%3E%20GAME%5B%22%E6%8F%90%E4%BA%A4%E7%AD%96%E7%95%A5%EF%BC%9A%E6%97%A9%E6%8C%82%2F%E6%99%9A%E6%8C%82%2F%E5%8F%8D%E6%8C%82%22%5D%0A%20%20GAME%20--%3E%20IN%0A%20%20IND%20--%3E%20CLR%7B%22%E6%B8%85%E7%AE%97%EF%BC%9A%E9%87%8F%E6%9C%80%E5%A4%A7%E4%BB%B7%E6%A0%BC%22%7D%0A%20%20CLR%20--%3E%20PRINT%5B%22%E5%8D%95%E4%B8%80%E4%BB%B7%E6%A0%BC%20print%22%5D%0A%20%20PRINT%20--%3E%20CONT%5B%22%E8%BF%9E%E7%BB%AD%E6%AE%B5%E6%8E%A5%E7%AE%A1%EF%BC%9A%E9%81%97%E7%95%99%E5%A4%B1%E8%A1%A1%E5%85%A5%E5%BC%80%E7%9B%98%E5%8A%A8%E5%8A%9B%E5%AD%A6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[n("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"竞价改变信息结构：连续段的订单是边际行动，竞价窗口的订单塑造所有人都看见的指示值——同一笔限价在两种机制里的信息外部性完全不同。价格发现集中的机制：一次性出清让知情单不必怕排队劣势，敢在窗口内放量，开盘竞价因此吸收相当一部分隔夜信息——日内形状开盘峰的来源；收盘竞价吸收指数与对冲需求。开盘后头几分钟由竞价遗留物决定：未配对方向的残余、出清价与共识价的偏离是开盘动力学的初始条件，第一课的耗尽模型从这里起跑。",-1)),a[5]||(a[5]=e("p",null,"两种机制里同一笔订单为何行为完全不同，可以并排对照：",-1)),(t(),B(o,null,{default:E(()=>[i(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20LR%0A%20%20subgraph%20CT%5B%22%E8%BF%9E%E7%BB%AD%E6%92%AE%E5%90%88%22%5D%0A%20%20%20%20A1%5B%22%E8%AE%A2%E5%8D%95%E5%8D%B3%E6%97%B6%E9%80%90%E7%AC%94%E6%88%90%E4%BA%A4%22%5D%20--%3E%20A2%5B%22%E6%97%B6%E9%97%B4%E4%BC%98%E5%85%88%E4%BF%9D%E6%8A%A4%E6%8E%92%E9%98%9F%E8%80%85%22%5D%0A%20%20%20%20A2%20--%3E%20A3%5B%22%E7%9F%A5%E6%83%85%E5%8D%95%E6%8B%86%E5%B0%8F%E9%9A%90%E8%97%8F%E6%84%8F%E5%9B%BE%22%5D%0A%20%20%20%20A3%20--%3E%20A4%5B%22%E4%BF%A1%E6%81%AF%E7%BC%93%E6%85%A2%E6%B8%97%E5%85%A5%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20end%0A%20%20subgraph%20AU%5B%22%E9%9B%86%E5%90%88%E7%AB%9E%E4%BB%B7%22%5D%0A%20%20%20%20B1%5B%22%E8%AE%A2%E5%8D%95%E5%85%88%E7%A7%AF%E7%B4%AF%E4%B8%8D%E5%87%BA%E6%B8%85%22%5D%20--%3E%20B2%5B%22%E6%97%A0%E6%97%B6%E9%97%B4%E4%BC%98%E5%85%88%3A%E4%BD%8D%E7%BD%AE%E6%97%A0%E6%84%8F%E4%B9%89%22%5D%0A%20%20%20%20B2%20--%3E%20B3%5B%22%E7%9F%A5%E6%83%85%E5%8D%95%E5%8F%AF%E7%AA%97%E5%8F%A3%E5%86%85%E6%94%BE%E9%87%8F%22%5D%0A%20%20%20%20B3%20--%3E%20B4%5B%22%E4%BF%A1%E6%81%AF%E4%B8%80%E6%AC%A1%E6%B3%A8%E5%85%A5%E5%87%BA%E6%B8%85%E4%BB%B7%22%5D%0A%20%20end%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">直觉类比：指示失衡像餐厅门口的等位牌——队伍越长，越吸引更多同向的客人加入（自我实现）；但也招来看见生意好而临时加座的老板多开桌子（反向单进场，自我限制）。两股力量的净值决定指示价最终能不能提前锁定出清价。</span></p><p>错误清单：把竞价成交量并进连续 K 线（上一课的三形状互检抓它）；用连续段速率外推竞价期间；忽视指示值公布时点，把公布后的订单激增当新信息；跨市场比较忽略次优价格规则与透明度差异。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>指示失衡不是承诺：最终出清价可以显著偏离最后指示值，尾盘博弈正是利用这个缝隙。数据粒度受披露制度约束，有的市场只公布快照，演化路径不可观测，对象退化成清算前后两点。竞价占比本身是体制变量：被动化与指数化持续改变它，「收盘形状」是会漂移的对象，历史平均要带截止日。竞价内的成交归因无法做：清算价里分不出边际推动者，冲击归因在这段天然缺位。</p><p><span class="marginnote">常见误区：初学者容易以为最后公布的指示价就是开盘价。实际上出清价取的是成交量最大化价格，尾盘几秒涌入的大单可以让它明显偏离几秒前的指示值——「尾盘偷袭」打的正是这个时间差，只看快照数据的人永远以为是跳空。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>竞价是单一价格批量清算：无时间优先、供需一次出清，连续段直觉在此整体失效。</li><li>竞价的对象是指示价与失衡的更新路径；公布时点是信息集跳变。</li><li>竞价数据必须与连续段分开：字典、速率、冲击、毒性全部分口径。</li><li>批量清算与连续撮合是机制光谱的两端（Budish–Cramton–Shim）。</li><li>出处：Harris, <em>Trading and Exchanges</em>, 2003；Budish, Cramton and Shim, <em>QJE</em>, 2015；规则对照见<a href="/quant/opening-closing-call">开盘与收盘集合竞价</a>。</li></ul>',7))])}const b=s(u,[["render",p]]);export{F as __pageData,b as default};
